1	import Phaser from 'phaser';
2	import { GAME_WIDTH, GAME_HEIGHT, BACKGROUND_COLOR } from './config/gameConfig';
3	import { BootScene } from './scenes/BootScene';
4	import { PreloadScene } from './scenes/PreloadScene';
5	import { MenuScene } from './scenes/MenuScene';
6	import { GameScene } from './scenes/GameScene';
7	import { ResultsScene } from './scenes/ResultsScene';
8	import { initAnalytics } from './analytics/track';
9	import { installOrientationGuard } from './ui/OrientationOverlay';
10	
11	// One-time page bootstrap: env-gated analytics loader (safe no-op without
12	// VITE_* ids) and the DOM orientation guard, both independent of Phaser.
13	initAnalytics();
14	installOrientationGuard();
15	
16	const config: Phaser.Types.Core.GameConfig = {
17	  type: Phaser.AUTO,
18	  parent: 'game',
19	  width: GAME_WIDTH, // fixed logical resolution 1280×720 (landscape 16:9)
20	  height: GAME_HEIGHT,
21	  backgroundColor: BACKGROUND_COLOR,
22	  scale: {
23	    mode: Phaser.Scale.FIT, // scale the logical canvas to fit any viewport…
24	    autoCenter: Phaser.Scale.CENTER_BOTH, // …and center it (letterbox on portrait)
25	  },
26	  physics: {
27	    default: 'arcade',
28	    arcade: {
29	      gravity: { x: 0, y: 0 }, // per-body gravity is set by entities in Phase 2
30	      debug: false,
31	    },
32	  },
33	  render: { antialias: true },
34	  // Scene order = boot flow: Boot → Preload → Menu → Game → Results.
35	  scene: [BootScene, PreloadScene, MenuScene, GameScene, ResultsScene],
36	};
37	
38	new Phaser.Game(config);
