1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { createButton } from '../ui/Button';
7	import { AudioManager } from '../systems/AudioManager';
8	
9	/**
10	 * MenuScene — title, Play (→ Game), and a persisted mute toggle. Fires no
11	 * analytics (start_game fires when the run actually begins, in GameScene).
12	 */
13	export class MenuScene extends Phaser.Scene {
14	  constructor() {
15	    super({ key: SceneKey.Menu });
16	  }
17	
18	  create(): void {
19	    const cx = GAME_WIDTH / 2;
20	
21	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.screen_bg_menu);
22	    this.add.image(cx, 180, KEYS.ui_title_logo);
23	
24	    this.add
25	      .text(cx, 180, t('menu_title'), {
26	        fontFamily: 'system-ui, sans-serif',
27	        fontSize: '54px',
28	        fontStyle: 'bold',
29	        color: '#20272e',
30	      })
31	      .setOrigin(0.5);
32	
33	    this.add
34	      .text(cx, 330, t('menu_subtitle'), {
35	        fontFamily: 'system-ui, sans-serif',
36	        fontSize: '24px',
37	        color: '#3a444d',
38	      })
39	      .setOrigin(0.5);
40	
41	    createButton(this, {
42	      x: cx,
43	      y: 450,
44	      texture: KEYS.ui_btn_play,
45	      label: t('menu_play'),
46	      onClick: () => this.scene.start(SceneKey.Game),
47	    });
48	
49	    this.add
50	      .text(cx, 550, t('menu_hint'), {
51	        fontFamily: 'system-ui, sans-serif',
52	        fontSize: '20px',
53	        color: '#3a444d',
54	      })
55	      .setOrigin(0.5);
56	
57	    this.buildMuteToggle();
58	  }
59	
60	  private buildMuteToggle(): void {
61	    const muteBtn = this.add
62	      .image(GAME_WIDTH - 52, 52, this.muteTexture())
63	      .setInteractive({ useHandCursor: true });
64	
65	    const label = this.add
66	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
67	        fontFamily: 'system-ui, sans-serif',
68	        fontSize: '14px',
69	        color: '#9fb0bd',
70	      })
71	      .setOrigin(0.5, 0);
72	
73	    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
74	      AudioManager.toggle(this.sound);
75	      muteBtn.setTexture(this.muteTexture());
76	      label.setText(this.muteLabel());
77	    });
78	  }
79	
80	  private muteTexture(): string {
81	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
82	  }
83	
84	  private muteLabel(): string {
85	    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
86	  }
87	}
