1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { ASSET_MANIFEST } from '../config/assetManifest';
4	import { AudioManager } from '../systems/AudioManager';
5	import { t } from '../i18n/strings';
6	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
7	
8	/**
9	 * PreloadScene — loads EVERY asset from the shared manifest (as SVGs at their
10	 * logical sizes) behind a loading bar, wires the iOS audio-unlock stub, then
11	 * advances to the menu. Nothing critical is lazy-loaded (spec §10.5).
12	 */
13	export class PreloadScene extends Phaser.Scene {
14	  constructor() {
15	    super({ key: SceneKey.Preload });
16	  }
17	
18	  preload(): void {
19	    this.buildLoadingBar();
20	
21	    // Register the first-gesture audio-unlock before anything could play audio.
22	    AudioManager.unlockOnFirstPointer(this);
23	
24	    // The manifest is the single source of truth: iterate & load each SVG.
25	    for (const a of ASSET_MANIFEST) {
26	      this.load.svg(a.key, a.path, { width: a.width, height: a.height });
27	    }
28	  }
29	
30	  create(): void {
31	    this.scene.start(SceneKey.Menu);
32	  }
