2	import { MUTE_STORAGE_KEY } from '../config/gameConfig';
3	
4	/**
5	 * AudioManager — mute state + persistence (spec §6.3) and the iOS audio-unlock
6	 * hook (spec §10.2). No audio assets are loaded in Phase 1; this manages the
7	 * game's sound manager (`scene.sound`) so mute is honoured the moment SFX/music
8	 * land in a later phase. Mute is a single persisted flag shared across scenes.
9	 */
10	
11	function readStoredMute(): boolean {
12	  try {
13	    return localStorage.getItem(MUTE_STORAGE_KEY) === '1';
14	  } catch {
15	    return false; // private mode / storage disabled
16	  }
17	}
18	
19	function persistMute(value: boolean): void {
20	  try {
21	    localStorage.setItem(MUTE_STORAGE_KEY, value ? '1' : '0');
22	  } catch {
23	    /* ignore — non-persistent session is acceptable */
24	  }
25	}
26	
27	let muted = readStoredMute();
28	
29	export const AudioManager = {
30	  isMuted(): boolean {
31	    return muted;
32	  },
33	
34	  /** Push the persisted mute state onto a game's sound manager. */
35	  apply(sound: Phaser.Sound.BaseSoundManager): void {
36	    sound.mute = muted;
37	  },
38	
39	  /** Toggle mute, persist, and apply. Returns the new muted state. */
40	  toggle(sound: Phaser.Sound.BaseSoundManager): boolean {
41	    muted = !muted;
42	    sound.mute = muted;
43	    persistMute(muted);
44	    return muted;
45	  },
46	
47	  /**
48	   * iOS Safari audio-unlock STUB. Web audio is suspended until a user gesture,
49	   * so resume the context on the first pointer input.
50	   * TODO(phase-5): verify on real iOS Safari once audio assets exist, and
51	   * confirm a muted player who taps Play stays muted through the unlock.
52	   */
53	  unlockOnFirstPointer(scene: Phaser.Scene): void {
54	    scene.input.once(Phaser.Input.Events.POINTER_DOWN, () => {
55	      const sound = scene.sound;
56	      if (
57	        sound instanceof Phaser.Sound.WebAudioSoundManager &&
58	        sound.context.state === 'suspended'
59	      ) {
60	        void sound.context.resume();
61	      }
62	    });
63	  },
64	};
